import { render, screen } from '@testing-library/react';
import { describe, expect, it, vi } from 'vitest';
import Header from './Header';

function noop() {
  return undefined;
}

describe('Header', () => {
  // Supersedes 011-R5: that test pinned the logo to the brand (orange) token because, at the
  // time, the Android app icon was a flat brand-coloured "H". The owner's 2026-10-09 "Konsept D"
  // decision (docs/design/mobile-redesign-spec.md section A) replaced the Android icon with the
  // two-tile present/correct mark generated by apps/mobile/scripts/generate-brand-assets.mjs; the
  // web logo now renders the same mark (BrandMark) so both surfaces match again.
  it('should render the two-tile brand mark for the logo button, hidden from assistive tech since the button is already labelled', () => {
    render(<Header onTitleClick={noop} onHelpClick={noop} onStatsClick={noop} onSettingsClick={noop} />);
    const logoButton = screen.getByLabelText('Ana Sayfa');
    const mark = logoButton.querySelector('svg');

    expect(mark).not.toBeNull();
    expect(mark?.getAttribute('aria-hidden')).toBe('true');
    expect(mark?.querySelectorAll('.fill-present').length).toBeGreaterThan(0);
    expect(mark?.querySelectorAll('.fill-correct').length).toBeGreaterThan(0);
  });

  it('should call onTitleClick when the logo or title is pressed', () => {
    const onTitleClick = vi.fn();
    render(<Header onTitleClick={onTitleClick} onHelpClick={noop} onStatsClick={noop} onSettingsClick={noop} />);
    screen.getByLabelText('Ana Sayfa').click();
    expect(onTitleClick).toHaveBeenCalledTimes(1);
  });
});
